local FEATS_OF_STRENGTH = 81   -- top-level category to ignore
local PVP_CATEGORY = 95        -- top-level "Player vs. Player", hidden by the Hide PvP setting
local BATCH_SIZE = 150         -- achievements processed per frame during a scan
local CATEGORY_BATCH_SIZE = 10 -- categories collected per frame during a scan
local MAX_CATEGORY_DEPTH = 5   -- guard for parent-chain walks
local DEFAULT_TOP = 15
local ROW_HEIGHT = 52
local ROW_SPACING = 4
local DETAIL_INDENT = 34           -- left offset of the unfolded detail text inside a card
local DETAIL_PAD = 8               -- padding above/below the detail text
