local scanning = false

local function Print(msg)
    print("|cff33ff99AlmostThere:|r " .. tostring(msg))
end

---------------------------------------------------------------------------
-- Category helpers
---------------------------------------------------------------------------
local function CategoryPath(catID)
    local parts = {}
    local topLevel = catID
    local guard = 0
    while catID and catID ~= -1 and guard < MAX_CATEGORY_DEPTH do
        local title, parent = GetCategoryInfo(catID)
        table.insert(parts, 1, title or "?")
        topLevel = catID
        catID = parent
        guard = guard + 1
    end
    return table.concat(parts, " > "), topLevel
end

---------------------------------------------------------------------------
-- Expansion helpers: prebuilt index in Data/Ratings.lua (x), else derived
-- from the category path
---------------------------------------------------------------------------
-- Order matters: Ratings.lua stores x as an index into this list (0-based),
-- keep it in sync with EXPANSIONS in tools/build_ratings.py
local EXPANSIONS = {
    "Classic", "The Burning Crusade", "Wrath of the Lich King", "Cataclysm",
    "Mists of Pandaria", "Warlords of Draenor", "Legion", "Battle for Azeroth",
    "Shadowlands", "Dragonflight", "The War Within", "Midnight",
}

-- Lower-cased category title -> canonical expansion name
local EXPANSION_LOOKUP = {
    ["vanilla"] = "Classic",
    ["burning crusade"] = "The Burning Crusade",
    ["wrath"] = "Wrath of the Lich King",
    ["mists"] = "Mists of Pandaria",
    ["warlords"] = "Warlords of Draenor",
    ["war within"] = "The War Within",
    -- Continents and features used as category names (e.g. "Quests > Northrend")
    ["eastern kingdoms"] = "Classic",
    ["kalimdor"] = "Classic",
    ["outland"] = "The Burning Crusade",
    ["northrend"] = "Wrath of the Lich King",
    ["lich king"] = "Wrath of the Lich King",
    ["argent tournament"] = "Wrath of the Lich King",
    ["pandaria"] = "Mists of Pandaria",
    ["proving grounds"] = "Mists of Pandaria",
    ["draenor"] = "Warlords of Draenor",
    ["battle raid"] = "Battle for Azeroth",
    ["battle dungeon"] = "Battle for Azeroth",
    ["island expeditions"] = "Battle for Azeroth",
    ["war effort"] = "Battle for Azeroth",
    ["heart of azeroth"] = "Battle for Azeroth",
    ["visions of n'zoth revisited"] = "Battle for Azeroth",
    ["covenant sanctums"] = "Shadowlands",
    ["torghast"] = "Shadowlands",
    ["dragon isles"] = "Dragonflight",
    ["dragon isle drake cosmetics"] = "Dragonflight",
    -- Remix events: filed under the expansion they replay
    ["legion remix"] = "Legion",
    ["remix: mists of pandaria"] = "Mists of Pandaria",
}
for _, name in ipairs(EXPANSIONS) do
    EXPANSION_LOOKUP[name:lower()] = name
end

-- "Lich King Raid", "Draenor Garrison" etc. fall back to the name without the suffix
local EXPANSION_SUFFIXES = { " raid", " dungeon", " scenarios", " garrison", " class hall" }

local function ExpansionFromPath(path)
    if not path then return nil end
    for segment in path:gmatch("[^>]+") do
        local key = segment:match("^%s*(.-)%s*$"):lower()
        if EXPANSION_LOOKUP[key] then return EXPANSION_LOOKUP[key] end
        for _, suffix in ipairs(EXPANSION_SUFFIXES) do
            if key:sub(-#suffix) == suffix then
                local base = EXPANSION_LOOKUP[key:sub(1, -#suffix - 1)]
                if base then return base end
            end
        end
    end
    return nil
end

local expansionByCategory = {}
local function GetExpansion(achID)
    local item = RATING_ITEMS[achID]
    local x = item and item.x
    if x then return EXPANSIONS[x + 1] end
    -- not in the shipped data (newer achievement): fall back to the category path
    local catID = GetAchievementCategory(achID)
    if not catID then return nil end
    local cached = expansionByCategory[catID]
    if cached == nil then
        cached = ExpansionFromPath((CategoryPath(catID))) or false
        expansionByCategory[catID] = cached
    end
    return cached or nil
end

local function IsKnownExpansion(name)
    for _, known in ipairs(EXPANSIONS) do
        if known == name then return true end
    end
    return false
end

-- nil = all expansions; persisted in AlmostThereDB.expansionFilter
local expansionFilter = nil
-- Effort filter state (nil = no filter, 1-5 = show only items with effort <= N)
local effortFilter = nil
-- Search box text, lowercased (nil = no search); matches name and reason
local searchText = nil
-- Hide the PvP category and its achievements; persisted in AlmostThereDB.hidePvP
local hidePvP = false

-- Category counts for the current entries + filters (see GetCategoryCounts)
local countsCache = nil
local function InvalidateCounts()
    countsCache = nil
end

---------------------------------------------------------------------------
-- Bookmarks: AlmostThereDB.bookmarks = { [achID] = time bookmarked }
---------------------------------------------------------------------------
local function IsBookmarked(id)
    return id and AlmostThereDB and AlmostThereDB.bookmarks and AlmostThereDB.bookmarks[id] ~= nil
end

local function ToggleBookmark(id)
    if not id then return end
    AlmostThereDB = AlmostThereDB or {}
    AlmostThereDB.bookmarks = AlmostThereDB.bookmarks or {}
    if AlmostThereDB.bookmarks[id] then
        AlmostThereDB.bookmarks[id] = nil
    else
        AlmostThereDB.bookmarks[id] = time()
    end
end

-- Drop bookmarks that are completed or no longer exist
local function PruneCompletedBookmarks()
    local bookmarks = AlmostThereDB and AlmostThereDB.bookmarks
    if not bookmarks then return end
    for id in pairs(bookmarks) do
        local _, name, _, completed = GetAchievementInfo(id)
        if not name or completed then bookmarks[id] = nil end
    end
end

---------------------------------------------------------------------------
-- Category tree & state
---------------------------------------------------------------------------
local rootCategories = {}
local categoryParentMap = {}
local expandedCategories = {}
local selectedCategoryID = "ALL"
-- "tree" = with subcategories, "flat" = top level only; persisted in AlmostThereDB.categoryMode
local categoryMode = "tree"
local UpdateCategoryList = nil

local function BuildCategoryHierarchy()
    rootCategories = {}
    categoryParentMap = {}
    InvalidateCounts()   -- counts roll up through categoryParentMap
    local catIDs = GetCategoryList()
    if not catIDs then return end

    local subcatsByParent = {}

    for _, catID in ipairs(catIDs) do
        local title, parent = GetCategoryInfo(catID)
        if title and title ~= "" then
            categoryParentMap[catID] = parent
            if not parent or parent == -1 then
                table.insert(rootCategories, { id = catID, title = title, subcategories = {} })
            else
                if not subcatsByParent[parent] then
                    subcatsByParent[parent] = {}
                end
                table.insert(subcatsByParent[parent], { id = catID, title = title, parent = parent })
            end
        end
    end

    for _, root in ipairs(rootCategories) do
        root.subcategories = subcatsByParent[root.id] or {}
    end
end

-- Iterates the parents of catID (nearest first) using the cached hierarchy
local function Ancestors(catID)
    local parent, guard = catID, 0
    return function()
        parent = categoryParentMap[parent]
        guard = guard + 1
        if parent and parent ~= -1 and guard <= MAX_CATEGORY_DEPTH then
            return parent
        end
    end
end

local function CategoryMatches(achCatID, filterCatID)
    if not filterCatID or filterCatID == "ALL" then return true end
    if not achCatID then return false end
    if achCatID == filterCatID then return true end
    for parent in Ancestors(achCatID) do
        if parent == filterCatID then return true end
    end
    return false
end

local function IsHiddenCategory(catID)
    return hidePvP and CategoryMatches(catID, PVP_CATEGORY)
end

---------------------------------------------------------------------------
-- Progress calculation
-- Returns: progress (0..1), remaining criteria (number), shownDone, shownTotal
---------------------------------------------------------------------------
local function GetProgress(id)
    local num = GetAchievementNumCriteria(id)
    if not num or num == 0 then
        return 0, 1, 0, 1
    end

    -- Single progress-bar criterion (e.g. "kill 250 mobs": 120/250)
    if num == 1 then
        local _, _, _, quantity, reqQuantity = GetAchievementCriteriaInfo(id, 1)
        if reqQuantity and reqQuantity > 1 then
            local p = math.min((quantity or 0) / reqQuantity, 1)
            return p, 1 - p, quantity or 0, reqQuantity
        end
    end

    local done = 0
    for i = 1, num do
        local _, _, completed = GetAchievementCriteriaInfo(id, i)
        if completed then done = done + 1 end
    end
    return done / num, num - done, done, num
end

-- Meta achievement: at least one criterion is another achievement (type 8)
local metaCache = {}
local function IsMetaAchievement(id)
    local cached = metaCache[id]
    if cached ~= nil then return cached end
    local isMeta = false
    for i = 1, GetAchievementNumCriteria(id) or 0 do
        local _, criteriaType = GetAchievementCriteriaInfo(id, i)
        if criteriaType == 8 then isMeta = true break end
    end
    metaCache[id] = isMeta
    return isMeta
end

---------------------------------------------------------------------------
-- Effort: baseline rating from Data/Ratings.lua (assumes zero progress),
-- re-evaluated with the player's scanned progress.
--   s = "g" grind     -> effort shrinks as the counter fills
--   s = "c" checklist -> effort shrinks with criteria done, unless a "hard"
--                        criterion (h) is still open
--   s = "s" single    -> progress does not matter
---------------------------------------------------------------------------
local UNRATED = { e = 3, s = "g", r = "Not rated yet" }

local function GetRating(id)
    return RATING_ITEMS[id] or UNRATED
end

local function Clamp(v, lo, hi)
    return math.max(lo, math.min(hi, v))
end

-- true/false = some/no hard criterion left; nil = none of them found in game
local function HardCriteriaLeft(id, hard)
    local want = {}
    for _, cid in ipairs(hard) do want[cid] = true end
    local matched, left = 0, false
    for i = 1, GetAchievementNumCriteria(id) or 0 do
        local _, _, completed, _, _, _, _, _, _, criteriaID = GetAchievementCriteriaInfo(id, i)
        if criteriaID and want[criteriaID] then
            matched = matched + 1
            if not completed then left = true end
        end
    end
    if matched == 0 then return nil end
    return left
end

-- a = scanned entry (progress, hardLeft) or nil for the baseline
local function EffortFor(id, a)
    local r = GetRating(id)
    local e = r.e or 3
    if not a or r.s == "s" then return e end
    local p = a.progress or 0
    if r.s == "c" then
        local cap = e
        if r.h and a.hardLeft ~= nil then
            if a.hardLeft then return e end
            cap = math.max(1, e - 1)   -- the hard part is done
        end
        return Clamp(math.ceil(1 + (e - 1) * (1 - p)), 1, cap)
    end
    -- grind: the curve keeps a half-done grind from looking easy too early
    return Clamp(math.ceil(1 + (e - 1) * (1 - p) ^ 0.7), 1, e)
end

-- Sort order: lowest effort first, then most progress, then most points
local function EasierFirst(x, y)
    if x.effort ~= y.effort then return x.effort < y.effort end
    if (x.progress or 0) ~= (y.progress or 0) then return (x.progress or 0) > (y.progress or 0) end
    if (x.points or 0) ~= (y.points or 0) then return (x.points or 0) > (y.points or 0) end
    return x.id < y.id
end

---------------------------------------------------------------------------
-- Recommendation list: scanned entries after a Scan, otherwise every rated
-- achievement the player has not completed (baseline effort). Cached.
---------------------------------------------------------------------------
local entriesCache = nil
local scanByID = nil         -- achID -> scanned entry, built on demand

local function InvalidateEntries()
    entriesCache = nil
    scanByID = nil
    countsCache = nil
end

-- Scanned entry for an achievement (name/points/category fallbacks), or nil
local function GetScanEntry(id)
    if not scanByID then
        scanByID = {}
        local scanned = AlmostThereDB and AlmostThereDB.achievements
        if scanned then
            for _, a in ipairs(scanned) do scanByID[a.id] = a end
        end
    end
    return scanByID[id]
end

local function MakeEntry(id, a)
    local _, name, points, completed, _, _, _, _, _, _, _, isGuild = GetAchievementInfo(id)
    if not name or completed or isGuild then return nil end
    local r = GetRating(id)
    return {
        id = id,
        cat = GetAchievementCategory(id),
        points = points or 0,
        progress = a and a.progress or 0,
        baseEffort = r.e or 3,
        effort = EffortFor(id, a),
        reason = r.r,
        details = r.d,
        search = (name .. " " .. (r.r or "")):lower(),
    }
end

local function GetEntries()
    if entriesCache then return entriesCache end
    local list = {}
    local function add(entry)
        if entry and not IsHiddenCategory(entry.cat) then
            list[#list + 1] = entry
        end
    end
    local scanned = AlmostThereDB and AlmostThereDB.achievements
    if scanned and #scanned > 0 then
        for _, a in ipairs(scanned) do
            add(MakeEntry(a.id, a))
        end
    else
        for id in pairs(RATING_ITEMS) do
            add(MakeEntry(id, nil))
        end
    end
    table.sort(list, EasierFirst)
    if AlmostThereDB then entriesCache = list end
    return list
end

local function HasScan()
    local scanned = AlmostThereDB and AlmostThereDB.achievements
    return scanned and #scanned > 0
end

-- Expansion + effort + search filters (category selection is handled separately)
local function PassesFilters(item)
    return (not expansionFilter or GetExpansion(item.id) == expansionFilter)
        and (not effortFilter or item.effort <= effortFilter)
        and (not searchText or item.search:find(searchText, 1, true) ~= nil)
end

-- Cached; cleared by InvalidateEntries and whenever a filter changes
local function GetCategoryCounts()
    if countsCache then return countsCache end
    local counts = {}
    local total = 0

    for _, item in ipairs(GetEntries()) do
        local catID = item.cat
        if PassesFilters(item) then
            total = total + 1
            if catID then
                counts[catID] = (counts[catID] or 0) + 1
                for parent in Ancestors(catID) do
                    counts[parent] = (counts[parent] or 0) + 1
                end
            end
        end
    end
    counts["ALL"] = total
    -- Like the entries, only cache once SavedVariables are loaded
    if AlmostThereDB then countsCache = counts end
    return counts
end

---------------------------------------------------------------------------
local updateScanStatusFunc = nil
local onScanDoneFunc = nil

---------------------------------------------------------------------------
-- Scan (spread over several frames to avoid a hitch)
---------------------------------------------------------------------------
local function Scan()
    if scanning then
        Print("Scan already running.")
        return
    end
    if InCombatLockdown() then
        Print("Can't scan during combat.")
        return
    end
    AlmostThereDB = AlmostThereDB or {}
    scanning = true
    if updateScanStatusFunc then updateScanStatusFunc() end
    Print("Scanning achievements...")

    -- Saved per entry: id, name, points, category (path), progress, hardLeft.
    -- Effort is recomputed from progress on load, so it is not stored.
    local categories = GetCategoryList() or {}
    local queue, seen = {}, {}
    local results = {}
    local collecting = true      -- phase 1: collect candidates, phase 2: progress
    local catIndex, index = 1, 1

    -- 1) collect candidate IDs, a few categories per frame
    local function CollectStep()
        local last = math.min(catIndex + CATEGORY_BATCH_SIZE - 1, #categories)
        for c = catIndex, last do
            local catID = categories[c]
            local path, top = CategoryPath(catID)
            if top ~= FEATS_OF_STRENGTH then
                for i = 1, GetCategoryNumAchievements(catID) or 0 do
                    local id, name, points, completed, _, _, _, _, _, _, _, isGuild =
                        GetAchievementInfo(catID, i)
                    if id and not completed and not isGuild and not seen[id] then
                        seen[id] = true
                        queue[#queue + 1] = {
                            id = id, name = name, points = points or 0,
                            category = path,
                        }
                    end
                end
            end
        end
        catIndex = last + 1
        if catIndex > #categories then collecting = false end
    end

    -- 2) compute progress in batches
    local function ProgressStep()
        local last = math.min(index + BATCH_SIZE - 1, #queue)
        for i = index, last do
            local a = queue[i]
            a.progress = GetProgress(a.id)
            local r = GetRating(a.id)
            if r.s == "c" and r.h then
                a.hardLeft = HardCriteriaLeft(a.id, r.h)
            end
            results[#results + 1] = a
        end
        index = last + 1
    end

    local RunStep
    local function Step()
        if collecting then
            CollectStep()
            C_Timer.After(0, RunStep)
            return
        end
        ProgressStep()
        if index <= #queue then
            C_Timer.After(0, RunStep)
        else
            AlmostThereDB.scanned = time()
            AlmostThereDB.character = UnitName("player") .. "-" .. GetRealmName()
            AlmostThereDB.achievements = results
            scanning = false
            InvalidateEntries()
            if updateScanStatusFunc then updateScanStatusFunc() end
            if onScanDoneFunc then onScanDoneFunc() end
            Print(string.format("Done. %d incomplete achievements found; effort now includes your progress.", #results))
        end
    end
    RunStep = function()
        local ok, err = pcall(Step)
        if not ok then
            scanning = false
            if updateScanStatusFunc then updateScanStatusFunc() end
            if collecting then
                Print(string.format("Scan failed at category %d of %d: %s", catIndex, #categories, tostring(err)))
            else
                Print(string.format("Scan failed at achievement %d of %d: %s", index, #queue, tostring(err)))
            end
        end
    end
    RunStep()
end

---------------------------------------------------------------------------
-- Chat output
---------------------------------------------------------------------------
local function ShowTop(n)
    local list = GetEntries()
    if #list == 0 then
        Print("No ratings found. Is Data\\Ratings.lua missing?")
        return
    end

    Print(string.format("Top %d easiest incomplete achievements%s:", n,
        HasScan() and "" or " (baseline - run /almostthere scan to include your progress)"))
    for i = 1, math.min(n, #list) do
        local e = list[i]
        local link = GetAchievementLink(e.id) or ("#" .. tostring(e.id))
        print(string.format("%2d. %s  |cffaaaaaa[effort %d/5, %d%%] %s|r",
            i, link, e.effort, math.floor(e.progress * 100), e.reason or ""))
    end
end

