-- "3/7 criteria (42%)" for multi-step achievements, nil otherwise
local function FormatCriteriaProgress(progress, done, total)
    if total and total > 1 then
        return string.format("|cff33ff99%d/%d criteria|r |cffaaaaaa(%d%%)|r",
            math.floor(done), math.floor(total), math.floor(progress * 100))
    end
end

-- Title, drag handling and close-button fix for a ButtonFrameTemplate window.
-- moveTarget is the frame that moves when dragging (the window itself, or its owner).
local function SetupWindowChrome(frame, title, moveTarget, hidePortrait)
    if frame.SetTitle then
        frame:SetTitle(title)
    elseif frame.TitleContainer and frame.TitleContainer.TitleText then
        frame.TitleContainer.TitleText:SetText(title)
    end
    if hidePortrait and ButtonFrameTemplate_HidePortrait then ButtonFrameTemplate_HidePortrait(frame) end
    if ButtonFrameTemplate_HideButtonBar then ButtonFrameTemplate_HideButtonBar(frame) end

    local function StartMoving() moveTarget:StartMoving() end
    local function StopMoving() moveTarget:StopMovingOrSizing() end
    if frame.TitleContainer then
        frame.TitleContainer:EnableMouse(true)
        frame.TitleContainer:RegisterForDrag("LeftButton")
        frame.TitleContainer:SetScript("OnDragStart", StartMoving)
        frame.TitleContainer:SetScript("OnDragStop", StopMoving)
    end
    frame:RegisterForDrag("LeftButton")
    frame:SetScript("OnDragStart", StartMoving)
    frame:SetScript("OnDragStop", StopMoving)

    -- Without the portrait the title bar spans the full width and covers the close button
    if hidePortrait and frame.CloseButton then
        local titleLevel = frame.TitleContainer and frame.TitleContainer:GetFrameLevel() or 0
        local nineSliceLevel = frame.NineSlice and frame.NineSlice:GetFrameLevel() or 0
        frame.CloseButton:SetFrameLevel(math.max(titleLevel, nineSliceLevel) + 10)
    end
end

-- UIPanelScrollFrameTemplate with a repositioned scrollbar, a scroll child that
-- tracks the frame width, and mouse-wheel scrolling by `step` pixels.
-- Anchor the returned scroll frame yourself. Returns scrollFrame, scrollChild, scrollBar.
local function CreateScrollArea(name, parent, childWidth, barX, barInset, step, onWidthChanged)
    local sf = CreateFrame("ScrollFrame", name, parent, "UIPanelScrollFrameTemplate")
    sf:EnableMouseWheel(true)

    local bar = sf.ScrollBar or _G[name .. "ScrollBar"]
    if bar then
        bar:ClearAllPoints()
        bar:SetPoint("TOPLEFT", sf, "TOPRIGHT", barX, -barInset)
        bar:SetPoint("BOTTOMLEFT", sf, "BOTTOMRIGHT", barX, barInset)
    end
    local child = CreateFrame("Frame", nil, sf)
    child:SetSize(childWidth, 1)
    sf:SetScrollChild(child)
    sf:SetScript("OnSizeChanged", function(_, width)
        if width and width > 0 then
            child:SetWidth(width)
            if onWidthChanged then onWidthChanged() end
        end
    end)
    sf:SetScript("OnMouseWheel", function(_, delta)
        if bar then
            local cur = bar:GetValue()
            local minVal, maxVal = bar:GetMinMaxValues()
            if delta < 0 then
                bar:SetValue(math.min(maxVal, cur + step))
            else
                bar:SetValue(math.max(minVal, cur - step))
            end
        end
    end)
    return sf, child, bar
end

-- Rows inside a scroll area pass the mouse wheel on to it
local function ForwardWheel(widget, scrollFrame)
    widget:EnableMouseWheel(true)
    widget:SetScript("OnMouseWheel", function(_, delta)
        local onMW = scrollFrame:GetScript("OnMouseWheel")
        if onMW then onMW(scrollFrame, delta) end
    end)
end

