do
    --local PORTRAIT_ICON = "Interface\\Icons\\Achievement_General"
    local PORTRAIT_ICON = "Interface\\AddOns\\AlmostThere\\Media\\almost_there.tga"
    if ResultsFrame.SetPortraitToAsset then
        ResultsFrame:SetPortraitToAsset(PORTRAIT_ICON)
    elseif ResultsFrame.PortraitContainer and ResultsFrame.PortraitContainer.portrait then
        SetPortraitToAsset(ResultsFrame.PortraitContainer.portrait, PORTRAIT_ICON)
    end
    -- Crop the icon's built-in border so the art sits centered in the portrait ring
    local portraitTex = ResultsFrame.GetPortrait and ResultsFrame:GetPortrait()
        or (ResultsFrame.PortraitContainer and ResultsFrame.PortraitContainer.portrait)
    local PORTRAIT_ZOOM = 1.2                          -- 1.0 = whole icon, higher = tighter crop
    local PORTRAIT_OFFSET_X, PORTRAIT_OFFSET_Y = 0.01, 0.02  -- texture units (e.g. 0.02) to pan the art
    if portraitTex then
        local half = 0.65 / PORTRAIT_ZOOM
        local cx, cy = 0.5 + PORTRAIT_OFFSET_X, 0.5 + PORTRAIT_OFFSET_Y
        portraitTex:SetTexCoord(cx - half, cx + half, cy - half, cy + half)
