-- Category rows are created on demand, so any number of expanded categories fits
local function GetCategoryButton(i)
    if catButtonPool[i] then return catButtonPool[i] end
    local btn = CreateFrame("Button", nil, catScrollInner, "BackdropTemplate")
    btn:SetHeight(CATEGORY_ROW_HEIGHT)
    btn:SetPoint("TOPLEFT", catScrollInner, "TOPLEFT", 0, -(i - 1) * (CATEGORY_ROW_HEIGHT + CATEGORY_ROW_SPACING))
    btn:SetPoint("TOPRIGHT", catScrollInner, "TOPRIGHT", 0, -(i - 1) * (CATEGORY_ROW_HEIGHT + CATEGORY_ROW_SPACING))
    btn:RegisterForClicks("LeftButtonUp")
    ForwardWheel(btn, catScrollFrame)

    btn:SetSize(CATEGORY_PANEL_WIDTH - 28, CATEGORY_ROW_HEIGHT)
    btn:SetFrameLevel(catScrollFrame:GetFrameLevel() + 2)

    btn:SetBackdrop(LIST_ROW_BACKDROP)
    btn:SetBackdropColor(0.1, 0.08, 0.06, 0.3)
    btn:SetBackdropBorderColor(0.4, 0.35, 0.25, 0.4)

    btn:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")

    local arrow = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    arrow:SetPoint("LEFT", btn, "LEFT", 4, 0)
    arrow:SetWidth(12)
    arrow:SetJustifyH("CENTER")

    local count = btn:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    count:SetPoint("RIGHT", btn, "RIGHT", -4, 0)
    count:SetJustifyH("RIGHT")

    local label = btn:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    label:SetPoint("LEFT", arrow, "RIGHT", 2, 0)
    label:SetPoint("RIGHT", count, "LEFT", -4, 0)
    label:SetJustifyH("LEFT")
    label:SetWordWrap(false)

    btn.Arrow = arrow
    btn.Label = label
    btn.Count = count

    btn:SetScript("OnClick", function(self)
        if not self.catData then return end
        local d = self.catData
        if d.isSummary then
            selectedCategoryID = "ALL"
        elseif d.isRoot then
            selectedCategoryID = d.id
            if d.hasChildren then
                expandedCategories[d.id] = not expandedCategories[d.id]
            end
        elseif d.isSubcat then
            selectedCategoryID = d.id
        end
        PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON)
        UpdateCategoryList()
        PopulateResults()
    end)

    btn:SetScript("OnEnter", function(self)
        if self.catData and self.catData.title then
            GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
            GameTooltip:AddLine(self.catData.title, 1, 0.82, 0)
            if self.catData.isSummary then
                GameTooltip:AddLine("Show all recommendations across all categories.", 1, 1, 1, true)
            elseif self.catData.hasChildren then
                GameTooltip:AddLine("Click to view achievements and toggle subcategories.", 1, 1, 1, true)
            else
                GameTooltip:AddLine("Click to view achievements in this category.", 1, 1, 1, true)
            end
            if self.catData.count then
                GameTooltip:AddLine(string.format("Items: |cff33ff99%d|r", self.catData.count), 0.8, 0.8, 0.8)
            end
            GameTooltip:Show()
        end
    end)
    btn:SetScript("OnLeave", GameTooltip_Hide)

    btn:Hide()
    catButtonPool[i] = btn
    return btn
end

UpdateCategoryList = function()
    if #rootCategories == 0 then
        BuildCategoryHierarchy()
    end

    local counts = GetCategoryCounts()

    local visible = {}
    visible[1] = {
        id = "ALL",
        title = "Summary",
        isSummary = true,
        count = counts["ALL"] or 0,
    }

    local flat = categoryMode == "flat"
    for _, root in ipairs(rootCategories) do
        if not (hidePvP and root.id == PVP_CATEGORY) then
            local hasChildren = not flat and #root.subcategories > 0
            visible[#visible + 1] = {
                id = root.id,
                title = root.title,
                isRoot = true,
                hasChildren = hasChildren,
                count = counts[root.id] or 0,
            }

            if hasChildren and expandedCategories[root.id] then
                for _, sub in ipairs(root.subcategories) do
                    visible[#visible + 1] = {
                        id = sub.id,
                        title = sub.title,
                        isSubcat = true,
                        count = counts[sub.id] or 0,
                    }
                end
            end
        end
    end

    for i = 1, math.max(#visible, #catButtonPool) do
        local d = visible[i]
        local btn = d and GetCategoryButton(i) or catButtonPool[i]
        if d then
            btn.catData = d
            local isSelected = (selectedCategoryID == d.id) or (selectedCategoryID == "ALL" and d.isSummary)

            if d.isSubcat then
                btn.Arrow:SetText("")
                btn.Label:ClearAllPoints()
                btn.Label:SetPoint("LEFT", btn, "LEFT", 18, 0)
                btn.Label:SetPoint("RIGHT", btn.Count, "LEFT", -4, 0)
            else
                btn.Label:ClearAllPoints()
                btn.Label:SetPoint("LEFT", btn.Arrow, "RIGHT", 2, 0)
                btn.Label:SetPoint("RIGHT", btn.Count, "LEFT", -4, 0)
                if d.hasChildren then
                    btn.Arrow:SetText(expandedCategories[d.id] and "|cffffe066v|r" or "|cff888888>|r")
                else
                    btn.Arrow:SetText("")
                end
            end

            btn.Label:SetText(d.title)

            if d.count and d.count > 0 then
                btn.Count:SetText(string.format("|cff33ff99%d|r", d.count))
            else
                btn.Count:SetText("|cff6666660|r")
            end

            if isSelected then
                btn:SetBackdropColor(0.25, 0.20, 0.12, 0.75)
                btn:SetBackdropBorderColor(1.0, 0.82, 0.0, 0.9)
                btn.Label:SetTextColor(1.0, 0.82, 0.0)
            else
                btn:SetBackdropColor(0.1, 0.08, 0.06, 0.3)
                btn:SetBackdropBorderColor(0.4, 0.35, 0.25, 0.4)
                if d.isSubcat then
                    btn.Label:SetTextColor(0.8, 0.8, 0.8)
                else
                    btn.Label:SetTextColor(0.95, 0.95, 0.95)
                end
            end

            btn:Show()
        else
            btn.catData = nil
            btn:Hide()
        end
    end

    catScrollInner:SetHeight(math.max(#visible * (CATEGORY_ROW_HEIGHT + CATEGORY_ROW_SPACING) + 6, 1))
end
