-- Toggle-window keybind (same ALMOSTTHERE_TOGGLE action as Key Bindings > Other)
do
    local ACTION = "ALMOSTTHERE_TOGGLE"
    local MODIFIER_KEYS = {
        LSHIFT = true, RSHIFT = true, LCTRL = true, RCTRL = true,
        LALT = true, RALT = true, LMETA = true, RMETA = true,
    }
    local keybindRow = CreateSettingsRow(3, "Toggle window keybind")
    local keybindBtn = CreateFrame("Button", nil, keybindRow, "UIPanelButtonTemplate")
    keybindBtn:SetSize(160, 26)
    keybindBtn:SetPoint("LEFT", keybindRow, "LEFT", SETTINGS_CONTROL_X + 26, 0)
    keybindBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")

    local function RefreshKeybind()
        local key = GetBindingKey(ACTION)
        keybindBtn:SetText(key and GetBindingText(key) or "|cff888888Not bound|r")
    end

    local function StopListening()
        keybindBtn:EnableKeyboard(false)
        keybindBtn.listening = false
        RefreshKeybind()
    end

    local function ApplyBinding(newKey)
        if InCombatLockdown() then
            print("|cffffd100AlmostThere:|r keybinds can't be changed in combat.")
            return
        end
        for _, old in ipairs({ GetBindingKey(ACTION) }) do
            SetBinding(old)
        end
        if newKey then
            local other = GetBindingAction(newKey)
            if other ~= "" and other ~= ACTION then
                print(("|cffffd100AlmostThere:|r %s was bound to %s; replaced."):format(
                    GetBindingText(newKey), GetBindingName(other)))
            end
            SetBinding(newKey, ACTION)
        end
        SaveBindings(GetCurrentBindingSet())
    end

    keybindBtn:SetScript("OnClick", function(self, button)
        if self.listening then return end
        if button == "RightButton" then
            ApplyBinding(nil)
            RefreshKeybind()
            return
        end
        self.listening = true
        self:SetText("Press a key...")
        self:EnableKeyboard(true)
    end)
    keybindBtn:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
        GameTooltip_SetTitle(GameTooltip, "Toggle window keybind")
        GameTooltip_AddNormalLine(GameTooltip, "Left-click, then press a key (with optional Shift/Ctrl/Alt). Esc cancels. Right-click clears.")
        GameTooltip:Show()
    end)
    keybindBtn:SetScript("OnLeave", GameTooltip_Hide)
    keybindBtn:SetScript("OnKeyDown", function(self, key)
        if not self.listening then
            self:SetPropagateKeyboardInput(true)
            return
        end
        self:SetPropagateKeyboardInput(false)
        if MODIFIER_KEYS[key] then return end
        if key ~= "ESCAPE" then
            if IsAltKeyDown() then key = "ALT-" .. key end
            if IsControlKeyDown() then key = "CTRL-" .. key end
            if IsShiftKeyDown() then key = "SHIFT-" .. key end
            ApplyBinding(key)
        end
        StopListening()
    end)
    keybindBtn:SetScript("OnHide", StopListening)

    keybindBtn:RegisterEvent("UPDATE_BINDINGS")
    keybindBtn:SetScript("OnEvent", RefreshKeybind)
    SettingsFrame:HookScript("OnShow", RefreshKeybind)
    RefreshKeybind()
end

