local Row_OnEnter
-- While the list is being wheel-scrolled, show the tooltip once scrolling
-- settles and only if the cursor is still on the same card
local function DeferRowTooltip(row)
    local id = row.id
    C_Timer.After(TOOLTIP_SCROLL_DELAY, function()
        if row.id == id and row:IsVisible() and row:IsMouseOver() then
            Row_OnEnter(row)
        end
    end)
end

Row_OnEnter = function(self)
    if not self.id then return end
    if GetTime() - lastWheelTime < TOOLTIP_SCROLL_DELAY then
        DeferRowTooltip(self)
        return
    end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    local link = GetAchievementLink(self.id)
    if link then
        GameTooltip:SetHyperlink(link)
    else
        local _, name, _, _, _, _, _, desc = GetAchievementInfo(self.id)
        GameTooltip:AddLine(name or ("Achievement #" .. self.id), 1, 0.82, 0)
        if desc and desc ~= "" then
            GameTooltip:AddLine(desc, 1, 1, 1, true)
        end
    end
    if self.effort then
        GameTooltip:AddLine(" ")
        if self.baseEffort and self.baseEffort ~= self.effort then
            GameTooltip:AddLine(string.format("Effort: %d/5  (base %d/5, adjusted for your progress)",
                self.effort, self.baseEffort), 1, 0.82, 0)
        else
            GameTooltip:AddLine(string.format("Effort: %d/5", self.effort), 1, 0.82, 0)
        end
    end
    if self.reason and self.reason ~= "" and not self.details then
        GameTooltip:AddLine(self.reason, 0.88, 0.88, 0.92, true)
    end
    GameTooltip:AddLine(" ")
    if self.details then
        GameTooltip:AddLine("|cff33ff99Click:|r Unfold / fold recommendation", 0.7, 0.7, 0.7)
        GameTooltip:AddLine("|cff33ff99Ctrl-Click:|r Open Achievement window", 0.7, 0.7, 0.7)
    else
        GameTooltip:AddLine("|cff33ff99Click:|r Open Achievement window", 0.7, 0.7, 0.7)
    end
    GameTooltip:AddLine("|cff33ff99Shift-Click:|r Link to chat", 0.7, 0.7, 0.7)
    GameTooltip:Show()
end

local function LoadAchievementUI()
    if AchievementFrame then return true end
    if C_AddOns and C_AddOns.LoadAddOn then
        pcall(C_AddOns.LoadAddOn, "Blizzard_AchievementUI")
    elseif UIParentLoadAddOn then
        pcall(UIParentLoadAddOn, "Blizzard_AchievementUI")
    elseif LoadAddOn then
        pcall(LoadAddOn, "Blizzard_AchievementUI")
    end
    if not AchievementFrame and AchievementFrame_LoadUI then
        pcall(AchievementFrame_LoadUI)
    end
    return AchievementFrame ~= nil
end

local function OpenToAchievement(achievementID)
    if not achievementID then return end
    local id = tonumber(achievementID) or achievementID

    if InCombatLockdown() then
        Print("Cannot open Achievement window while in combat.")
        return
    end

    LoadAchievementUI()

    -- Modern WoW (Patch 12.1+ / Midnight / The War Within)
    if ShowAchievementFrameForAchievement then
        ShowAchievementFrameForAchievement(id)
    -- Classic / earlier retail expansions
    elseif OpenAchievementFrameToAchievement then
        OpenAchievementFrameToAchievement(id)
    elseif AchievementFrame then
        if not AchievementFrame:IsShown() then
            if AchievementFrame_ToggleAchievementFrame then
                AchievementFrame_ToggleAchievementFrame()
            elseif ToggleAchievementFrame then
                ToggleAchievementFrame()
            elseif ShowUIPanel then
                ShowUIPanel(AchievementFrame)
            else
                AchievementFrame:Show()
            end
        end
        if AchievementFrame_SelectAchievement then
            AchievementFrame_SelectAchievement(id)
        end
    end

    -- Ensure AchievementFrame is visible and raised in front of ResultsFrame
    if AchievementFrame then
        if not AchievementFrame:IsShown() then
            if ShowUIPanel then
                ShowUIPanel(AchievementFrame)
            else
                AchievementFrame:Show()
            end
        end
        if AchievementFrame.Raise then
            AchievementFrame:Raise()
        end
    end
end

