UpdateBookmarkPanel = function()
    PruneCompletedBookmarks()
    if not bookmarkPanel:IsShown() then return end

    -- Oldest bookmark first
    local bookmarks = (AlmostThereDB and AlmostThereDB.bookmarks) or {}
    local ids = {}
    for id in pairs(bookmarks) do ids[#ids + 1] = id end
    table.sort(ids, function(a, b)
        if bookmarks[a] ~= bookmarks[b] then return bookmarks[a] < bookmarks[b] end
        return a < b
    end)

    for i = 1, math.max(#ids, #bookmarkRows) do
        local id = ids[i]
        local btn = id and GetBookmarkRow(i) or bookmarkRows[i]
        if id then
            local _, name = GetAchievementInfo(id)
            local progress, _, done, total = GetProgress(id)
            btn.id = id
            btn.Title:SetText(name or ("Achievement #" .. id))
            btn.Criteria:SetText(FormatCriteriaProgress(progress, done, total) or "|cffffcc00Incomplete|r")
            btn:Show()
        else
            btn.id = nil
            btn:Hide()
        end
    end

    bmEmpty:SetShown(#ids == 0)
    bmScrollInner:SetHeight(math.max(#ids * (BOOKMARK_ROW_HEIGHT + BOOKMARK_ROW_SPACING) + 6, 1))
end
-- Also fires when the window opens with the drawer already out
bookmarkPanel:SetScript("OnShow", UpdateBookmarkPanel)

-- Criteria updates come in bursts; refresh the open drawer at most once a second
local bookmarkRefreshPending = false
local function QueueBookmarkRefresh()
    if bookmarkRefreshPending or not bookmarkPanel:IsVisible() then return end
    bookmarkRefreshPending = true
    C_Timer.After(1, function()
        bookmarkRefreshPending = false
        UpdateBookmarkPanel()
    end)
end

-- Tab on the right edge that opens/collapses the drawer, drawn with the same atlases as the
-- Character Info window's bottom tabs (PanelTabButtonTemplate), turned to hang off the right edge
local bookmarkTab = CreateFrame("Button", nil, ResultsFrame)
bookmarkTab:SetSize(BOOKMARK_TAB_WIDTH, 120)
bookmarkTab:SetFrameLevel(bookmarkPanel:GetFrameLevel())

do
    -- Atlas turned 90° counter-clockwise: the tab's top edge (joined to the window) faces left,
    -- its right cap ends up on top and its left cap at the bottom. Returns the piece's new height.
    local function SetRotatedAtlas(tex, atlas)
        local info = C_Texture.GetAtlasInfo(atlas)
        if not info then return 0 end
        local l, r, t, b = info.leftTexCoord, info.rightTexCoord, info.topTexCoord, info.bottomTexCoord
        tex:SetTexture(info.file or info.filename)
        tex:SetTexCoord(r, t, l, t, r, b, l, b)
        tex:SetWidth(info.height)
        return info.width
    end

    local function CreatePieces(layer, alpha)
        local pieces = {}
        for _, key in ipairs({ "Top", "Middle", "Bottom" }) do
            local tex = bookmarkTab:CreateTexture(nil, layer)
            if alpha then
                tex:SetBlendMode("ADD")
                tex:SetAlpha(alpha)
            end
            pieces[key] = tex
        end
        pieces.Top:SetPoint("TOPLEFT")
        pieces.Bottom:SetPoint("BOTTOMLEFT")
        pieces.Middle:SetPoint("TOPLEFT", pieces.Top, "BOTTOMLEFT")
        pieces.Middle:SetPoint("BOTTOMLEFT", pieces.Bottom, "TOPLEFT")
        return pieces
    end

    local normal = CreatePieces("BACKGROUND")
    local highlight = CreatePieces("HIGHLIGHT", 0.4)

    -- Only one tab, so it always uses the unselected look
    for _, pieces in ipairs({ normal, highlight }) do
        pieces.Top:SetHeight(SetRotatedAtlas(pieces.Top, "uiframe-tab-right"))
        SetRotatedAtlas(pieces.Middle, "_uiframe-tab-center")
        pieces.Bottom:SetHeight(SetRotatedAtlas(pieces.Bottom, "uiframe-tab-left"))
    end

    -- Label reads top to bottom (rotated 90° clockwise), centered on the tab
    local bookmarkTabLabel = bookmarkTab:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    if bookmarkTabLabel.SetRotation then
        bookmarkTabLabel:SetText("Bookmarks")
        bookmarkTabLabel:SetRotation(-math.pi / 2)
        -- The rotated glyphs land off the anchor; nudge them back onto the tab's center
        bookmarkTabLabel:SetPoint("CENTER", bookmarkTab, "CENTER", 5, -7)
    else
        bookmarkTabLabel:SetPoint("CENTER", bookmarkTab, "CENTER", 0, -4)
        -- Older clients without FontString rotation: stack the letters instead
        bookmarkTabLabel:SetText(("Bookmarks"):gsub("(.)", "%1\n"):sub(1, -2))
        bookmarkTabLabel:SetSpacing(-2)
    end
end

local function SetBookmarkPanelShown(shown)
    bookmarkPanel:SetShown(shown)
    if AlmostThereDB then AlmostThereDB.bookmarksOpen = shown or nil end
    bookmarkTab:ClearAllPoints()
    if shown then
