    if IsBookmarked(row.id) then
        tex:SetTexture(BOOKMARK_FILLED_TEX)
        tex:SetVertexColor(1, 0.82, 0)
        tex:SetAlpha(1.0)
    else
        tex:SetTexture(BOOKMARK_TEX)
        tex:SetVertexColor(0.9, 0.85, 0.65)
        tex:SetAlpha(0.6)
    end
end

-- Result cards (achievement card style), virtualized: the list holds every
-- matching entry, but only the cards in view are backed by frames. Each
-- card's place in the scroll child comes from cardTops / cardHeights.
local listItems = {}            -- filtered entries currently listed
local cardTops, cardHeights = {}, {}
local expandedRows = {}         -- achievement id -> true while its card is unfolded
local activeRows = {}           -- list index -> card frame bound to it
local freeRows = {}             -- card frames not bound to any index
local detailWidth = 50          -- width of the unfolded detail text

-- Invisible copy of a card's detail text, used to measure unfolded heights
-- for cards that are not on screen (kept shown so its height is measured)
local detailMeasure = scrollInner:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
detailMeasure:SetPoint("TOPLEFT", scrollInner, "TOPLEFT", 0, 0)
detailMeasure:SetJustifyH("LEFT")
detailMeasure:SetJustifyV("TOP")
detailMeasure:SetSpacing(2)
detailMeasure:SetAlpha(0)

local function ItemDetails(item)
    local details = item.details
    if details and details ~= "" then return details end
end

local function CardHeight(item)
    local details = ItemDetails(item)
    if not (details and expandedRows[item.id]) then return ROW_HEIGHT end
    detailMeasure:SetWidth(detailWidth)
    detailMeasure:SetText(details)
    return ROW_HEIGHT + DETAIL_PAD + detailMeasure:GetStringHeight() + DETAIL_PAD + OPEN_BTN_HEIGHT + 6
end

-- Card chrome per state, mirroring Blizzard's achievement frame:
-- meta cards get a blue border/title bar, completed cards a gold body.
local CARD_STYLES = {
    normal = {
        bg = { 0.08, 0.07, 0.06, 0.45 }, border = { 0.65, 0.55, 0.35, 0.6 },
        strip = { 1, 1, 1 }, stripAlpha = 0.35,
    },
    completed = {
        bg = { 0.30, 0.20, 0.06, 0.55 }, border = { 0.90, 0.70, 0.25, 0.8 },
        strip = { 1.0, 0.85, 0.5 }, stripAlpha = 0.35,
    },
    meta = {
        bg = { 0.05, 0.12, 0.16, 0.55 }, border = { 0.25, 0.70, 0.85, 0.8 },
        strip = { 0.3, 0.7, 1.0 }, stripAlpha = 0.55,
    },
    metaCompleted = {
        bg = { 0.30, 0.20, 0.06, 0.55 }, border = { 0.25, 0.70, 0.85, 0.8 },
        strip = { 0.3, 0.7, 1.0 }, stripAlpha = 0.55,
    },
}

-- Cards are pooled, so every value is set on each call
local function ApplyRowStyle(row, isMeta, completed)
    local style
    if isMeta then
        style = completed and CARD_STYLES.metaCompleted or CARD_STYLES.meta
    else
        style = completed and CARD_STYLES.completed or CARD_STYLES.normal
    end
    row:SetBackdropColor(unpack(style.bg))
    row:SetBackdropBorderColor(unpack(style.border))
    row.TitleStrip:SetVertexColor(unpack(style.strip))
    row.TitleStrip:SetAlpha(style.stripAlpha)
end

local function Row_OnClick(self)
    local id = self.id
    local fold
    if self.details and not IsControlKeyDown() then
        fold = function()
            expandedRows[id] = not expandedRows[id] or nil
            LayoutRows()
        end
    end
    HandleAchievementClick(id, fold)
end

local function CreateCardRow()
    local row = CreateFrame("Button", nil, scrollInner, "BackdropTemplate")
    row:SetHeight(ROW_HEIGHT)
    row:RegisterForClicks("LeftButtonUp")
    ForwardWheel(row, scrollFrame)

    -- Card backdrop with subtle bronze/gold border
    row:SetBackdrop(PANEL_BACKDROP)
    row:SetBackdropColor(0.08, 0.07, 0.06, 0.45)
    row:SetBackdropBorderColor(0.65, 0.55, 0.35, 0.6)

    -- Signature Achievement title bar strip along the top
    local titleStrip = row:CreateTexture(nil, "BACKGROUND", nil, 1)
    titleStrip:SetPoint("TOPLEFT", row, "TOPLEFT", 3, -3)
    titleStrip:SetPoint("TOPRIGHT", row, "TOPRIGHT", -3, -3)
    titleStrip:SetHeight(18)
    titleStrip:SetTexture("Interface\\AchievementFrame\\UI-Achievement-Borders")
    titleStrip:SetTexCoord(0, 0.9765625, 0.66015625, 0.73828125)
    titleStrip:SetAlpha(0.35)
    row.TitleStrip = titleStrip

    -- Hover highlight
    row:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")

    -- Fixed-height header area; the unfolded detail text is laid out below it
    local head = CreateFrame("Frame", nil, row)
    head:SetPoint("TOPLEFT", row, "TOPLEFT", 0, 0)
    head:SetPoint("TOPRIGHT", row, "TOPRIGHT", 0, 0)
    head:SetHeight(ROW_HEIGHT)

    -- 1) Rank index
    local indexLabel = row:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    indexLabel:SetPoint("LEFT", head, "LEFT", 21, 0)   -- same center as before, room for 4 digits
    indexLabel:SetWidth(30)
    indexLabel:SetJustifyH("CENTER")

    -- 2) Achievement Icon
    local iconTex = row:CreateTexture(nil, "ARTWORK")
    iconTex:SetSize(36, 36)
    iconTex:SetPoint("LEFT", head, "LEFT", 50, 0)
    iconTex:SetTexCoord(0.08, 0.92, 0.08, 0.92)

    -- 3) Icon border frame (classic golden square border)
    local iconBorder = row:CreateTexture(nil, "OVERLAY")
    iconBorder:SetSize(48, 48)
    iconBorder:SetPoint("CENTER", iconTex, "CENTER", -1, 1)
    iconBorder:SetTexture("Interface\\AchievementFrame\\UI-Achievement-IconFrame")
    iconBorder:SetTexCoord(0, 0.5625, 0, 0.5625)

    -- 4) Shield & Points on right
    local shield = row:CreateTexture(nil, "ARTWORK")
    shield:SetSize(36, 34)
    shield:SetPoint("RIGHT", head, "RIGHT", -10, 0)
    shield:SetTexture("Interface\\AchievementFrame\\UI-Achievement-Shields")
    shield:SetTexCoord(0, 0.5, 0, 0.45)

    local pointsLabel = row:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    pointsLabel:SetPoint("CENTER", shield, "CENTER", -1, 1)
    pointsLabel:SetJustifyH("CENTER")

    -- 5) Bookmark toggle (half the icon size, in the left column below the expand button) + Achievement Name
    local bookmarkBtn = CreateFrame("Button", nil, row)
    bookmarkBtn:SetSize(26, 32)
    bookmarkBtn:SetFrameLevel(row:GetFrameLevel() + 5)
    bookmarkBtn:SetPoint("TOP", head, "TOPLEFT", 15, -18)
    local bookmarkTex = bookmarkBtn:CreateTexture(nil, "ARTWORK")
    bookmarkTex:SetAllPoints()
    bookmarkTex:SetTexture(BOOKMARK_TEX)
    local bookmarkHl = bookmarkBtn:CreateTexture(nil, "HIGHLIGHT")
    bookmarkHl:SetAllPoints()
    bookmarkHl:SetTexture(BOOKMARK_FILLED_TEX)
    bookmarkHl:SetVertexColor(1, 1, 1)
    bookmarkHl:SetAlpha(0.35)
    bookmarkBtn.Tex = bookmarkTex
    bookmarkBtn:SetScript("OnClick", function(self)
        ToggleBookmark(row.id)
        PlaySound(IsBookmarked(row.id) and SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON
            or SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_OFF)
        UpdateRowBookmarkStar(row)
        UpdateBookmarkPanel()
        self:GetScript("OnEnter")(self)   -- refresh the tooltip text
    end)
    bookmarkBtn:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
        GameTooltip:SetText(IsBookmarked(row.id) and "Remove bookmark" or "Bookmark")
        GameTooltip:AddLine("Track progress in the bookmarks panel", 0.8, 0.8, 0.8)
        GameTooltip:Show()
    end)
