    local nameLabel = row:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    nameLabel:SetPoint("TOPLEFT", iconTex, "TOPRIGHT", 12, 1)
    nameLabel:SetPoint("RIGHT", shield, "LEFT", -28, 1)
    nameLabel:SetJustifyH("LEFT")
