    local copyBtn = CreateFrame("Button", nil, row)
    copyBtn:SetSize(14, 14)
    local copyTex = copyBtn:CreateTexture(nil, "ARTWORK")
    copyTex:SetAllPoints()
    copyTex:SetTexture("Interface\\AddOns\\AlmostThere\\Media\\copy")
    copyTex:SetVertexColor(0.75, 0.68, 0.45)
    copyTex:SetAlpha(0.4)
    local copyHl = copyBtn:CreateTexture(nil, "HIGHLIGHT")
    copyHl:SetAllPoints()
    copyHl:SetTexture("Interface\\AddOns\\AlmostThere\\Media\\copy")
