    catLabel:SetPoint("TOPLEFT", nameLabel, "BOTTOMLEFT", 0, -2)
    catLabel:SetPoint("RIGHT", shield, "LEFT", -10, 0)
    catLabel:SetJustifyH("LEFT")
    catLabel:SetWordWrap(false)

    -- 7b) Effort star gauge (5 stars using bundled star texture)
    local STAR_SIZE = 14   -- px per star texture
    local STAR_GAP  = 2    -- px between stars
    local GAUGE_W   = STAR_SIZE * 5 + STAR_GAP * 4
    local starGauge = CreateFrame("Frame", nil, row)
    starGauge:SetSize(GAUGE_W, STAR_SIZE)
    starGauge:SetPoint("RIGHT", shield, "LEFT", -10, -9)
