    -- 7) AI Reason / Explanation  (stops before the star gauge)
    local reasonLabel = row:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    reasonLabel:SetPoint("TOPLEFT", catLabel, "BOTTOMLEFT", 0, -2)
    reasonLabel:SetPoint("RIGHT", starGauge, "LEFT", -6, 0)
    reasonLabel:SetJustifyH("LEFT")
    reasonLabel:SetWordWrap(false)

    -- Fold chevron (only shown for rows that have detailed text)
    local chevron = row:CreateTexture(nil, "OVERLAY")
    chevron:SetSize(16, 16)
    chevron:SetPoint("TOPLEFT", row, "TOPLEFT", 26, -4)
    chevron:Hide()

    -- Unfolded detail text + "open achievement" button
    local detailLabel = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
    detailLabel:SetPoint("TOPLEFT", head, "BOTTOMLEFT", DETAIL_INDENT, -DETAIL_PAD)
    detailLabel:SetJustifyH("LEFT")
    detailLabel:SetJustifyV("TOP")
    detailLabel:SetSpacing(2)
    detailLabel:SetTextColor(0.88, 0.88, 0.92)
    detailLabel:Hide()

    local openBtn = CreateFrame("Button", nil, row, "UIPanelButtonTemplate")
    openBtn:SetSize(130, OPEN_BTN_HEIGHT)
    openBtn:SetPoint("BOTTOMRIGHT", row, "BOTTOMRIGHT", -10, 6)
    openBtn:SetText("Open Achievement")
    openBtn:SetScript("OnClick", function() OpenToAchievement(row.id) end)
    openBtn:Hide()

    row.Chevron = chevron
    row.DetailLabel = detailLabel
    row.OpenBtn = openBtn
    row.IndexLabel = indexLabel
    row.IconTex = iconTex
    row.IconBorder = iconBorder
    row.Shield = shield
    row.PointsLabel = pointsLabel
    row.NameLabel = nameLabel
    row.CopyBtn = copyBtn
    row.BookmarkBtn = bookmarkBtn
    row.CatLabel = catLabel
    row.ReasonLabel = reasonLabel
    row.StarGauge = starGauge
    row.Stars = stars

    row:SetScript("OnEnter", Row_OnEnter)
    row:SetScript("OnLeave", GameTooltip_Hide)
    row:SetScript("OnClick", Row_OnClick)

    row:Hide()
    return row
end

-- Fill a card frame with list entry `index` and put it in place
local function BindRow(row, index)
    local item = listItems[index]
    local id = item.id

    row:SetHeight(cardHeights[index])
    row:ClearAllPoints()
    row:SetPoint("TOPLEFT", scrollInner, "TOPLEFT", 2, -cardTops[index])
    row:SetPoint("TOPRIGHT", scrollInner, "TOPRIGHT", -2, -cardTops[index])

    local _, name, points, completed, _, _, _, _, _, icon = GetAchievementInfo(id)
    local dbEntry = GetScanEntry(id)

    name = name or (dbEntry and dbEntry.name) or ("Achievement #" .. id)
    points = points or (dbEntry and dbEntry.points) or 0
    icon = icon or "Interface\\Icons\\Achievement_General"

    row.id = id
    ApplyRowStyle(row, IsMetaAchievement(id), completed)
    row.effort = item.effort
    row.baseEffort = item.baseEffort
    row.reason = item.reason
    row.details = ItemDetails(item)
    row.DetailLabel:SetText(row.details or "")

    row.IndexLabel:SetText(index)
    row.IconTex:SetTexture(icon)

    if completed then
        row.NameLabel:SetText(string.format("|cff88ff88%s|r |cffaaaaaa(Completed)|r", name))
    else
        row.NameLabel:SetText(name)
    end
    row.name = name
    UpdateRowBookmarkStar(row)
    row.CopyBtn:ClearAllPoints()
    row.CopyBtn:SetPoint("LEFT", row.NameLabel, "LEFT",
        math.min(row.NameLabel:GetStringWidth(), row.NameLabel:GetWidth()) + 4, 0)

    if points > 0 then
        row.Shield:SetTexture("Interface\\AchievementFrame\\UI-Achievement-Shields")
        row.PointsLabel:SetText(points)
        row.PointsLabel:Show()
    else
        row.Shield:SetTexture("Interface\\AchievementFrame\\UI-Achievement-Shields-NoPoints")
        row.PointsLabel:Hide()
    end

    local catPath = (dbEntry and dbEntry.category)
    if not catPath or catPath == "" then
        local catID = GetAchievementCategory(id)
        catPath = catID and CategoryPath(catID) or ""
    end

    local progStr
    if completed then
        progStr = "|cff33ff99Completed|r"
    else
        local progress, _, done, total = GetProgress(id)
        progStr = FormatCriteriaProgress(progress, done, total) or "|cffffcc00Incomplete|r"
    end

    if catPath ~= "" then
        row.CatLabel:SetText(string.format("|cffb8a890%s|r   |cff555555•|r   %s", catPath, progStr))
    else
        row.CatLabel:SetText(progStr)
    end

    -- Drive the star gauge from the (progress-adjusted) effort
    local effortLevel = item.effort
    if effortLevel then
        row.StarGauge:Show()
        local fillColor = EFFORT_PALETTE[effortLevel] or EFFORT_PALETTE[3]
        for s = 1, 5 do
            if s <= effortLevel then
                row.Stars[s]:SetAlpha(1.0)
                row.Stars[s]:SetVertexColor(fillColor[1], fillColor[2], fillColor[3])
            else
                row.Stars[s]:SetAlpha(0.20)
                row.Stars[s]:SetVertexColor(0.7, 0.65, 0.45)  -- dim gold outline
            end
        end
    else
        row.StarGauge:Hide()
    end

    row.ReasonLabel:SetText(FormatReason(item.reason))

    -- Fold state: unfolded cards show the detail text and the open button
    local expanded = row.details and expandedRows[id]
    if expanded then
        row.DetailLabel:SetWidth(detailWidth)
        row.DetailLabel:Show()
        row.OpenBtn:Show()
    else
        row.DetailLabel:Hide()
        row.OpenBtn:Hide()
    end
    if row.details then
        row.Chevron:SetTexture(expanded and "Interface\\Buttons\\UI-MinusButton-Up"
            or "Interface\\Buttons\\UI-PlusButton-Up")
        row.Chevron:Show()
    else
        row.Chevron:Hide()
    end

    row:Show()
end

local function ReleaseRow(index)
    local row = activeRows[index]
    activeRows[index] = nil
    row.id, row.effort, row.baseEffort, row.reason, row.details = nil, nil, nil, nil, nil
    row:Hide()
    freeRows[#freeRows + 1] = row
end

-- Bind frames to the cards inside the scrolled view and release the rest.
-- rebind = true refreshes cards that stay in view (data or layout changed).
local function RenderVisibleRows(rebind)
    local n = #listItems
    local top = scrollFrame:GetVerticalScroll()
    local viewHeight = scrollFrame:GetHeight()
    if not viewHeight or viewHeight <= 0 then viewHeight = ResultsFrame:GetHeight() end
    local bottom = top + viewHeight

    -- First card whose bottom edge is below the top of the view
    local first, hi = 1, n
    while first < hi do
        local mid = math.floor((first + hi) / 2)
        if cardTops[mid] + cardHeights[mid] < top then first = mid + 1 else hi = mid end
    end
    local last = first - 1
    while last < n and cardTops[last + 1] <= bottom do last = last + 1 end

    for index in pairs(activeRows) do
        if index < first or index > last then ReleaseRow(index) end
    end
    for index = first, last do
        local row = activeRows[index]
        if not row then
            row = table.remove(freeRows) or CreateCardRow()
            activeRows[index] = row
            BindRow(row, index)
        elseif rebind then
            BindRow(row, index)
        end
    end
end
scrollFrame:HookScript("OnVerticalScroll", function() RenderVisibleRows(false) end)

-- Stack the listed cards; unfolded cards grow to fit their detail text
LayoutRows = function()
    detailWidth = math.max(scrollInner:GetWidth() - 4 - DETAIL_INDENT - 12, 50)
    local y = 2
    for i, item in ipairs(listItems) do
        local height = CardHeight(item)
        cardTops[i], cardHeights[i] = y, height
        y = y + height + ROW_SPACING
    end
    for i = #listItems + 1, #cardTops do
        cardTops[i], cardHeights[i] = nil, nil
    end
    scrollInner:SetHeight(math.max(y + 4, 1))
    RenderVisibleRows(true)
end

-- Fill the window from the recommendation list (filtered by category, expansion, effort)
PopulateResults = function()
    UpdateScanButtons()
    local isAll = (selectedCategoryID == nil or selectedCategoryID == "ALL")

    -- Entries are already sorted easiest-first; list every match
    local items = {}
    for _, item in ipairs(GetEntries()) do
        if (isAll or CategoryMatches(item.cat, selectedCategoryID)) and PassesFilters(item) then
            items[#items + 1] = item
        end
    end
    listItems = items
    local numItems = #items

    -- Show/hide the clear-filter × button
    clearFilterBtn:SetShown(effortFilter ~= nil)

    if numItems == 0 then
        if isAll then
            emptyTitle:SetText("No Recommendations Found")
            if searchText then
                emptyDesc:SetText("Nothing matches your search.\nTry another word or clear the search box.")
            elseif effortFilter or expansionFilter then
                emptyDesc:SetText("Nothing matches the current filters.\nTry a higher effort level or another expansion.")
            else
                emptyDesc:SetText("No rated achievements to show.\nClick |cff33ff99Scan|r to inspect your incomplete achievements.")
            end
        else
            local catTitle = GetCategoryInfo(selectedCategoryID) or ("Category #" .. tostring(selectedCategoryID))
            emptyTitle:SetText("No Incomplete Achievements")
            emptyDesc:SetText(string.format("No incomplete achievements or recommendations found in |cffffe066%s|r.\nTry selecting another category or run a Scan.", catTitle))
        end
        emptyState:Show()
        LayoutRows()   -- releases every card
        scrollInner:SetHeight(1)
        return 0
    end

    emptyState:Hide()
    LayoutRows()
    return numItems
end

RefreshResultStars = function()
    for _, row in pairs(activeRows) do
        UpdateRowBookmarkStar(row)
    end
end

-- Refresh the window when ratings change (scan finished, achievement earned)
local function RefreshAfterDataChange()
    InvalidateEntries()
    if ResultsFrame:IsShown() then
        UpdateCategoryList()
        PopulateResults()
    end
    UpdateLDBText()
end
onScanDoneFunc = RefreshAfterDataChange

ResultsFrame:SetScript("OnShow", function(self)
    PlaySound(SOUNDKIT.IG_CHARACTER_INFO_OPEN)
    UpdateCategoryList()
    PopulateResults()
end)
-- One handler for everything that closes with the main window
ResultsFrame:SetScript("OnHide", function(self)
    PlaySound(SOUNDKIT.IG_CHARACTER_INFO_CLOSE)
    SettingsFrame:Hide()
    helpOverlay:Hide()
end)

local function ToggleResults()
    if ResultsFrame:IsShown() then
        ResultsFrame:Hide()
    else
        ResultsFrame:Show()
    end
end

