SLASH_ALMOSTTHERE1 = "/almostthere"
SlashCmdList["ALMOSTTHERE"] = function(input)
    local cmd, arg = strsplit(" ", strtrim(input or ""), 2)
    cmd = (cmd or ""):lower()

    if cmd == "scan" then
        Scan()
    elseif cmd == "top" or cmd == "" then
        ShowTop(tonumber(arg) or DEFAULT_TOP)
    elseif cmd == "results" then
        ResultsFrame:Show()
    else
        Print("Commands:")
        print("  /almostthere scan        - scan your progress and re-evaluate effort")
        print("  /almostthere top [n]     - show the n easiest (default " .. DEFAULT_TOP .. ")")
        print("  /almostthere results     - open the recommendations window")
    end
end

