        tooltip:AddLine("AlmostThere", 0.2, 1, 0.6)
        tooltip:AddLine(" ")
        tooltip:AddLine("Left-click: toggle recommendations window", 1, 1, 1)
        tooltip:AddLine("Right-click: open Achievement UI", 0.7, 0.7, 0.7)
    end,
})

-- Same number as the Summary row (respects expansion + effort filters)
UpdateLDBText = function()
    local count = GetCategoryCounts()["ALL"]
    if count > 0 then
        ldbObject.text = string.format("|cff33ff99AlmostThere|r |cffffd700(%d)|r", count)
    else
        ldbObject.text = "|cff33ff99AlmostThere|r"
    end
end


---------------------------------------------------------------------------
-- Init
---------------------------------------------------------------------------
do
    -- Achievements are often earned in bursts (meta chains): refresh once per burst
    local achievementRefreshPending = false
    local function QueueAchievementRefresh()
        if achievementRefreshPending then return end
        achievementRefreshPending = true
        C_Timer.After(0.2, function()
            achievementRefreshPending = false
            RefreshAfterDataChange()
            UpdateBookmarkPanel()
        end)
    end

    local frame = CreateFrame("Frame")
    frame:RegisterEvent("ADDON_LOADED")
    frame:SetScript("OnEvent", function(self, event, name)
        if event == "ACHIEVEMENT_EARNED" then
            QueueAchievementRefresh()
            return
        elseif event == "CRITERIA_UPDATE" then
            QueueBookmarkRefresh()
            return
        elseif event == "PLAYER_LOGIN" then
            UpdateLDBText()
            return
        end
        if name ~= ADDON_NAME then return end
        self:UnregisterEvent("ADDON_LOADED")
        self:RegisterEvent("PLAYER_LOGIN")
        self:RegisterEvent("ACHIEVEMENT_EARNED")
        self:RegisterEvent("CRITERIA_UPDATE")

        AlmostThereDB = AlmostThereDB or {}
        AlmostThereDB.bookmarks = AlmostThereDB.bookmarks or {}
        SetBookmarkPanelShown(AlmostThereDB.bookmarksOpen == true)
        InvalidateEntries()
        -- A saved expansion that is no longer in the list would hide everything
        if AlmostThereDB.expansionFilter and not IsKnownExpansion(AlmostThereDB.expansionFilter) then
            AlmostThereDB.expansionFilter = nil
        end
        expansionFilter = AlmostThereDB.expansionFilter
        expansionDropdown:GenerateMenu()
        categoryMode = AlmostThereDB.categoryMode or "tree"
        categoryModeDropdown:GenerateMenu()
        hidePvP = AlmostThereDB.hidePvP == true
        hidePvPCheck:SetChecked(hidePvP)

        UpdateMinimapPosition()
        BuildCategoryHierarchy()
        UpdateCategoryList()

        Print("loaded. Type /almostthere for commands.")
    end)
end